const taskDeliveredTrips = `-- name: TaskDeliveredTrips :many
SELECT tr.id FROM trip_records tr WHERE tr.task_id = $1::uuid AND tr.status = 'delivered' ORDER BY tr.id
`

// The delivered trips of a task (task.plan_date_changed restamps or reprices each).
func (q *Queries) TaskDeliveredTrips(ctx context.Context, taskID uuid.UUID) ([]uuid.UUID, error) {
	rows, err := q.db.Query(ctx, taskDeliveredTrips, taskID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []uuid.UUID{}
	for rows.Next() {
		var id uuid.UUID
		if err := rows.Scan(&id); err != nil {
			return nil, err
		}
		items = append(items, id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

